import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.airscale.genericairscale import GenericAirscale


class Adet(GenericAirscale):
    """Adet command class."""

    def __init__(self, connection, options, adet_scripts="/opt/hwmt/python/hwapi/AdetS.py", prompt=None, newline_chars=None, runner=None):
        """
        Adet command checks all board status of gNB.

        :param connection: moler connection to device, terminal when command is executed
        :param options: command options as string
        :param adet_scripts: adet scripts to be executed in fct.
                              Maybe the scripts depend on some libraries not in python library search path.
                              User need add the path including those libraries into python library search path.
                              e.g  export PYTHONPATH=/opt/hwmt/python
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command

        """
        super(Adet, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.adet_scripts = adet_scripts
        self.current_ret["BOARD_STATUS"] = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"python {self.adet_scripts} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse received line to get expected value.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_board_status(line)
            except ParsingDone:
                pass
        return super(Adet, self).on_new_line(line, is_full_line)

    # regex to find expected board name and board status
    _re_board_status = re.compile(r"0x[\dA-Fa-f]{2,}\s+(?P<BOARD_NAME>\w+)\s+(?P<BOARD_STATUS>\w+)\[\d+\]")

    def _parse_board_status(self, line):
        """
        Parse output of command to extract board name and board status.

        :param line: output of command
        :return: None but raises ParsingDone if line has board name and board status.
        """
        if self._regex_helper.search_compiled(Adet._re_board_status, line):
            self.current_ret["BOARD_STATUS"].update({self._regex_helper.group("BOARD_NAME"): self._regex_helper.group("BOARD_STATUS")})
            raise ParsingDone


